1	pub struct Customer {
2	    years_with_mhpco: u32,
3	}
4	
5	impl Customer {
6	    pub fn new(years_with_mhpco: u32) -> Self {
7	        Self { years_with_mhpco }
8	    }
9	
10	    /// A long-standing customer has done business with the MHPCO for years.
11	    fn is_long_standing(&self) -> bool {
12	        self.years_with_mhpco >= LOYALTY_YEARS
13	    }
14	}
15	
16	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
17	pub enum ItemType {
18	    Sword,
19	    Amulet,
20	    Staff,
21	    Potion,
22	    Rune,
23	    Moonstone,
24	}
25	
26	impl ItemType {
27	    /// The MHPCO price-list row for a main item, or `None` for a component:
28	    /// components are not on the main price list, they are charged per type
29	    /// by `component_charge`.
30	    fn main_item_base_premium(self) -> Option<f64> {
31	        match self {
32	            Self::Sword => Some(100.0),
33	            Self::Amulet => Some(60.0),
34	            Self::Staff => Some(80.0),
35	            Self::Potion => Some(40.0),
36	            Self::Rune | Self::Moonstone => None,
37	        }
38	    }
39	
40	    pub fn parse(name: &str) -> Result<Self, String> {
41	        match name {
42	            "sword" => Ok(Self::Sword),
43	            "amulet" => Ok(Self::Amulet),
44	            "staff" => Ok(Self::Staff),
45	            "potion" => Ok(Self::Potion),
46	            "rune" => Ok(Self::Rune),
47	            "moonstone" => Ok(Self::Moonstone),
48	            unknown => Err(format!("the MHPCO does not insure items of type '{unknown}'")),
49	        }
50	    }
51	}
52	
53	pub struct Item {
54	    item_type: ItemType,
55	    cursed: bool,
56	    enchantment: u32,
57	}
58	
59	impl Item {
60	    pub fn new(item_type: ItemType) -> Self {
61	        Self {
62	            item_type,
63	            cursed: false,
64	            enchantment: 0,
65	        }
66	    }
67	
68	    /// The item's enchantment level, as recorded by the MHPCO.
69	    pub fn with_enchantment(mut self, enchantment: u32) -> Self {
70	        self.enchantment = enchantment;
71	        self
72	    }
73	
74	    /// A cursed item carries the MHPCO's risk surcharge.
75	    pub fn cursed(mut self) -> Self {
76	        self.cursed = true;
77	        self
78	    }
79	
80	    /// The item-specific risk surcharges this item carries, charged against the
81	    /// item's own base premium rather than the policy total. A component carries
82	    /// none: the MHPCO records no curse, enchantment or material for one, so it
83	    /// is never an affected item.
84	    fn item_surcharge(&self) -> f64 {
85	        match self.item_type.main_item_base_premium() {
86	            Some(item_base) => item_base * self.risk_surcharge_rate(),
87	            None => 0.0,
88	        }
89	    }
90	
91	    /// Highly enchanted for rating purposes. The MHPCO reads a separate, higher
92	    /// enchantment threshold when reimbursing damage, so this one is named for
93	    /// the premium it surcharges.
94	    fn is_highly_enchanted(&self) -> bool {
95	        self.enchantment >= HIGH_ENCHANTMENT_LEVEL
96	    }
97	
98	    /// Curse and high enchantment are independent risks; an item carrying both
99	    /// is surcharged for both.
100	    fn risk_surcharge_rate(&self) -> f64 {
101	        let curse = if self.cursed { CURSE_SURCHARGE } else { 0.0 };
102	        let enchantment = if self.is_highly_enchanted() {
103	            HIGH_ENCHANTMENT_SURCHARGE
104	        } else {
105	            0.0
106	        };
107	        curse + enchantment
108	    }
109	}
110	
111	const PROCESSING_FEE: u64 = 5;
112	const FIRST_INSURANCE_SURCHARGE: f64 = 0.10;
113	/// Cursed items add a risk surcharge on their own base premium.
114	const CURSE_SURCHARGE: f64 = 0.50;
115	/// Long-standing customers -- 2 or more years of business with the MHPCO --
116	/// receive a loyalty discount on the policy base premium.
117	const LOYALTY_YEARS: u32 = 2;
118	const LOYALTY_DISCOUNT: f64 = 0.20;
119	/// Customers receive a discount on each contract after their first.
120	const FOLLOW_UP_CONTRACT_DISCOUNT: f64 = 0.15;
121	/// Highly enchanted items -- enchantment level 5 or above -- add a risk
122	/// surcharge on their own base premium.
123	const HIGH_ENCHANTMENT_LEVEL: u32 = 5;
124	const HIGH_ENCHANTMENT_SURCHARGE: f64 = 0.30;
125	/// Components -- for example runes and moonstones -- share one price-list row.
126	const COMPONENT_BASE_PREMIUM: f64 = 25.0;
127	
128	/// Premiums are rounded up: the MHPCO's favour is the larger amount.
129	fn round_premium_in_mhpco_favour(amount: f64) -> u64 {
130	    amount.ceil() as u64
131	}
132	
133	/// The policy-wide modifier rate, charged against the policy base premium --
134	/// the sum of all item base premiums. The MHPCO nets its policy-wide modifiers
135	/// against one another: a first insurance carries an initial assessment
136	/// surcharge, a long-standing customer earns a loyalty discount, and every
137	/// contract after the customer's first earns a follow-up discount.
138	fn policy_modifier_rate(customer: &Customer, contract: Contract) -> f64 {
139	    let loyalty = if customer.is_long_standing() {
140	        LOYALTY_DISCOUNT
141	    } else {
142	        0.0
143	    };
144	    let follow_up = match contract {
145	        Contract::First => 0.0,
146	        Contract::FollowUp => FOLLOW_UP_CONTRACT_DISCOUNT,
147	    };
148	    FIRST_INSURANCE_SURCHARGE - loyalty - follow_up
149	}
150	
151	/// A building block of exactly 3 alike components is offered at this price
152	/// instead of the per-component base premium.
153	const COMPONENT_BLOCK_SIZE: usize = 3;
154	const COMPONENT_BLOCK_BASE_PREMIUM: f64 = 60.0;
155	
156	/// Alike components -- components of the very same type -- are charged as a
157	/// block when there are exactly 3 of them.
158	const COMPONENT_TYPES: [ItemType; 2] = [ItemType::Rune, ItemType::Moonstone];
159	
160	fn component_charge(alike_count: usize) -> f64 {
161	    if alike_count == COMPONENT_BLOCK_SIZE {
162	        COMPONENT_BLOCK_BASE_PREMIUM
163	    } else {
164	        alike_count as f64 * COMPONENT_BASE_PREMIUM
165	    }
166	}
167	
168	/// How many of the policy's items are alike the given component type. Alike
169	/// components are the ones charged together, so this is where the MHPCO's
170	/// reading of "alike" lives.
171	fn alike_component_count(items: &[Item], component_type: ItemType) -> usize {
172	    items
173	        .iter()
174	        .filter(|item| item.item_type == component_type)
175	        .count()
176	}
177	
178	/// Main items are charged one price-list row each, individually.
179	fn main_items_base_premium(items: &[Item]) -> f64 {
180	    items
181	        .iter()
182	        .filter_map(|item| item.item_type.main_item_base_premium())
183	        .sum()
184	}
185	
186	/// Components are charged per group of alike components, so that a group of
187	/// exactly 3 earns the block price.
188	fn component_blocks_base_premium(items: &[Item]) -> f64 {
189	    COMPONENT_TYPES
190	        .iter()
191	        .map(|component_type| component_charge(alike_component_count(items, *component_type)))
192	        .sum()
193	}
194	
195	/// The policy base premium is the sum of the items' base premiums, with alike
196	/// components charged as blocks.
197	pub fn policy_base_premium(items: &[Item]) -> f64 {
198	    main_items_base_premium(items) + component_blocks_base_premium(items)
199	}
200	
201	/// Item-specific modifiers apply to the base premium of the affected item, not
202	/// to the policy total.
203	fn item_surcharges(items: &[Item]) -> f64 {
204	    items.iter().map(Item::item_surcharge).sum()
205	}
206	
207	/// A customer's first contract with the MHPCO, or any contract after it.
208	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
209	pub enum Contract {
210	    First,
211	    FollowUp,
212	}
213	
214	/// What the MHPCO rates this policy at, as an exact fraction: the policy base
215	/// premium, modified policy-wide for the customer and the contract, plus the
216	/// surcharges carried by the individual affected items. This is the rating
217	/// decision; it is deliberately unrounded and carries no processing fee.
218	fn rated_premium(customer: &Customer, items: &[Item], contract: Contract) -> f64 {
219	    let policy_base = policy_base_premium(items);
220	    policy_base + policy_base * policy_modifier_rate(customer, contract) + item_surcharges(items)
221	}
222	
223	/// The premium the customer is billed: the MHPCO rates the policy, then settles
224	/// it -- rounding the rated amount in its own favour and adding the processing
225	/// fee at the very end.
226	pub fn quote(customer: &Customer, items: &[Item], contract: Contract) -> u64 {
227	    round_premium_in_mhpco_favour(rated_premium(customer, items, contract)) + PROCESSING_FEE
228	}
229	
230	#[cfg(test)]
