cat > /tmp/trial.py <<'PY'
import re
p='src/lib.rs'
s=open(p).read()

# 1. Add is_component predicate next to main_item_base_premium, and make COMPONENT_TYPES
#    the single source by deriving main_item_base_premium's None from it is not possible in
#    a const fn match; instead name the concept and use it at the surcharge site.
old = """    pub fn parse(name: &str) -> Result<Self, String> {"""
new = """    /// A component -- for example a rune or a moonstone -- is not on the main
    /// price list: the MHPCO charges components per group of alike components
    /// instead, and records no curse, enchantment or material for one.
    fn is_component(self) -> bool {
        self.main_item_base_premium().is_none()
    }

    pub fn parse(name: &str) -> Result<Self, String> {"""
assert old in s
s = s.replace(old, new, 1)

# 2. item_surcharge: express the exemption in component vocabulary.
old = """    fn item_surcharge(&self) -> f64 {
        match self.item_type.main_item_base_premium() {
            Some(item_base) => item_base * self.risk_surcharge_rate(),
            None => 0.0,
        }
    }"""
new = """    fn item_surcharge(&self) -> f64 {
        match self.item_type.main_item_base_premium() {
            Some(item_base) if !self.item_type.is_component() => {
                item_base * self.risk_surcharge_rate()
            }
            _ => 0.0,
        }
    }"""
assert old in s
s = s.replace(old, new, 1)
open(p,'w').write(s)
PY
python3 /tmp/trial.py && cargo test --offline 2>&1 | grep -E "^test result|^warning|^error" | head

